        CONSTRAINT "PK_FgsInventoryCategory" PRIMARY KEY ("Id"),
        CONSTRAINT "UQ_FgsInventoryCategory_TenantId_CompanyId_CategoryCode" UNIQUE ("TenantId", "CompanyId", "CategoryCode"),
        CONSTRAINT "FK_FgsInventoryCategory_FgsTenantCompany_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES dbo."FgsTenantCompany" ("TenantId", "CompanyNumber") ON DELETE RESTRICT
