DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM dbo."__EFMigrationsHistory" WHERE "MigrationId" = '20260525172237_AddVendorAndInventoryCatalogTables') THEN
    CREATE TABLE dbo."FgsVendor" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "VendorCode" character varying(50) NOT NULL,
        "Name" character varying(200) NOT NULL,
        "LegalName" character varying(200),
        "VendorType" character varying(50) NOT NULL,
        "PaymentTermId" bigint,
        "Email" character varying(255),
        "PhoneNumber" character varying(50),
        "MobileNumber" character varying(50),
        "Website" character varying(255),
        "TaxIdentificationNumber" character varying(100),
        "LicenseNumber" character varying(100),
        "InsurancePolicyNumber" character varying(100),
        "Notes" text,
        "Is1099Eligible" boolean NOT NULL DEFAULT FALSE,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_FgsVendor" PRIMARY KEY ("Id"),
        CONSTRAINT "UQ_FgsVendor_TenantId_CompanyId_VendorCode" UNIQUE ("TenantId", "CompanyId", "VendorCode"),
        CONSTRAINT "CK_FgsVendor_VendorType" CHECK ("VendorType" IN ('VENDOR', 'SUBCONTRACTOR')),
        CONSTRAINT "FK_FgsVendor_FgsSetupPaymentTerm" FOREIGN KEY ("PaymentTermId") REFERENCES dbo."FgsSetupPaymentTerm" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsVendor_FgsTenantCompany_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES dbo."FgsTenantCompany" ("TenantId", "CompanyNumber") ON DELETE RESTRICT
    );
    COMMENT ON TABLE dbo."FgsVendor" IS 'Stores vendor and subcontractor master information for purchasing, AP, and subcontractor management.';
    COMMENT ON COLUMN dbo."FgsVendor"."VendorType" IS 'Allowed values: VENDOR, SUBCONTRACTOR';
    COMMENT ON COLUMN dbo."FgsVendor"."PaymentTermId" IS 'References payment terms used for accounts payable due date calculation.';
    COMMENT ON COLUMN dbo."FgsVendor"."Is1099Eligible" IS 'Indicates whether vendor should be included in 1099 reporting.';
    END IF;
END $EF$;

