        CONSTRAINT "UQ_FgsInventoryItem_TenantId_CompanyId_ItemCode" UNIQUE ("TenantId", "CompanyId", "ItemCode"),
        CONSTRAINT "FK_FgsInventoryItem_FgsInventoryCategory" FOREIGN KEY ("InventoryCategoryId") REFERENCES dbo."FgsInventoryCategory" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsInventoryItem_FgsInventoryItemType" FOREIGN KEY ("InventoryItemTypeId") REFERENCES dbo."FgsInventoryItemType" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsInventoryItem_FgsInventorySubCategory" FOREIGN KEY ("InventorySubCategoryId") REFERENCES dbo."FgsInventorySubCategory" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsInventoryItem_FgsTenantCompany_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES dbo."FgsTenantCompany" ("TenantId", "CompanyNumber") ON DELETE RESTRICT
    );
    COMMENT ON TABLE dbo."FgsInventoryItem" IS 'Inventory item master record for purchasing, sales, and stock tracking.';
    END IF;
END $EF$;

