        CONSTRAINT "PK_FgsInventoryStock" PRIMARY KEY ("Id"),
        CONSTRAINT "UQ_FgsInventoryStock_TenantId_CompanyId_InventoryItemId" UNIQUE ("TenantId", "CompanyId", "InventoryItemId"),
        CONSTRAINT "FK_FgsInventoryStock_FgsInventoryItem" FOREIGN KEY ("InventoryItemId") REFERENCES dbo."FgsInventoryItem" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsInventoryStock_FgsTenantCompany_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES dbo."FgsTenantCompany" ("TenantId", "CompanyNumber") ON DELETE RESTRICT
