DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM dbo."__EFMigrationsHistory" WHERE "MigrationId" = '20260525172237_AddVendorAndInventoryCatalogTables') THEN
    CREATE TABLE dbo."FgsVendorInventoryItem" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "VendorId" bigint NOT NULL,
        "InventoryItemId" bigint NOT NULL,
        "VendorPartNumber" character varying(100),
        "VendorPartName" character varying(200),
        "LastCost" numeric(18,2) NOT NULL DEFAULT 0.0,
        "LastReceivedDate" timestamptz,
        "PurchaseOrderComments" text,
        "IsPreferredVendor" boolean NOT NULL DEFAULT FALSE,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_FgsVendorInventoryItem" PRIMARY KEY ("Id"),
        CONSTRAINT "UQ_FgsVendorInventoryItem_TenantId_CompanyId_VendorId_InventoryItemId" UNIQUE ("TenantId", "CompanyId", "VendorId", "InventoryItemId"),
        CONSTRAINT "FK_FgsVendorInventoryItem_FgsInventoryItem" FOREIGN KEY ("InventoryItemId") REFERENCES dbo."FgsInventoryItem" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsVendorInventoryItem_FgsTenantCompany_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES dbo."FgsTenantCompany" ("TenantId", "CompanyNumber") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsVendorInventoryItem_FgsVendor" FOREIGN KEY ("VendorId") REFERENCES dbo."FgsVendor" ("Id") ON DELETE RESTRICT
    );
    COMMENT ON TABLE dbo."FgsVendorInventoryItem" IS 'Stores vendor-specific inventory item relationships, vendor part information, pricing, and purchasing defaults.';
    COMMENT ON COLUMN dbo."FgsVendorInventoryItem"."VendorPartNumber" IS 'Vendor-specific part number for the inventory item.';
    COMMENT ON COLUMN dbo."FgsVendorInventoryItem"."LastCost" IS 'Last received cost from the vendor based on purchase order receiving.';
    COMMENT ON COLUMN dbo."FgsVendorInventoryItem"."LastReceivedDate" IS 'Last date inventory was received from the vendor.';
    COMMENT ON COLUMN dbo."FgsVendorInventoryItem"."PurchaseOrderComments" IS 'Comments automatically copied to purchase orders for this vendor item combination.';
    COMMENT ON COLUMN dbo."FgsVendorInventoryItem"."IsPreferredVendor" IS 'Indicates whether this vendor is the preferred vendor for the inventory item.';
    END IF;
END $EF$;

